package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.scheduling.rules.*;import com.rpb.reservation.workforce.scheduling.SchedulingDtos.*;import com.rpb.reservation.workforce.attendance.*;import com.rpb.reservation.workforce.approval.*;import static com.rpb.reservation.workforce.scheduling.rules.AttendanceRules.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class AttendanceJudgementTest {
 Instant start=Instant.parse("2026-11-01T03:00:00Z"),end=start.plusSeconds(43200);UUID employee=UUID.randomUUID(),store=UUID.randomUUID();
 AttendanceRules rules(String grace,List<BreakRule> breaks){return new AttendanceRules(1,breaks,5,5,0,grace,List.of(new AnomalyRule("LATE","迟到",true,true),new AnomalyRule("EARLY","早退",true,true),new AnomalyRule("MISSING","缺卡",true,false),new AnomalyRule("ABSENCE","旷工",true,true),new AnomalyRule("LEAVE","请假",true,false)),null,null);}
 Schedule schedule(AttendanceRules r){var shift=new Shift(UUID.randomUUID(),"11-23","11:00","23:00",false,"none",0,0,0,0,false,true,1,r);return new Schedule(UUID.randomUUID(),employee,"A","001",shift.id(),LocalDate.of(2026,11,1),start,end,"Asia/Singapore","scheduled",shift,UUID.randomUUID(),1);}
 AttendanceDtos.Session session(Schedule s,Instant in,Instant out){return new AttendanceDtos.Session(UUID.randomUUID(),s.id(),employee,store,in,out,null,List.of(),false,1);}
 @Test void latenessAndEarlinessExcludeApprovedLeaveAndGraceCanCountOnlyExcess(){var s=schedule(rules("excess",List.of()));var leaves=List.of(new ApprovalCalculator.LeaveSlice(start,start.plusSeconds(3600),true));var findings=new AttendanceJudgement().findings(s,session(s,start.plusSeconds(3960),end.minusSeconds(360)),leaves,end.plusSeconds(1));assertThat(findings).filteredOn(f->f.code().equals("LATE")).singleElement().extracting(ApprovalDtos.Finding::seconds).isEqualTo(60L);assertThat(findings).filteredOn(f->f.code().equals("EARLY")).singleElement().extracting(ApprovalDtos.Finding::seconds).isEqualTo(60L);var full=schedule(rules("full",List.of()));assertThat(new AttendanceJudgement().findings(full,session(full,start.plusSeconds(360),end),List.of(),end.plusSeconds(1))).singleElement().extracting(ApprovalDtos.Finding::seconds).isEqualTo(360L);}
 @Test void aClockInDuringPlannedBreakOnlyCountsMissedWorkingSeconds(){var s=schedule(rules("excess",List.of(new BreakRule("rest","休息","window",0,60,null,"none",false))));assertThat(new AttendanceJudgement().findings(s,session(s,start.plusSeconds(1800),end),List.of(),end.plusSeconds(1))).isEmpty();}
 @Test void anOptionalActualBreakWindowDoesNotCreateAssumedRestForLateness(){var s=schedule(rules("excess",List.of(new BreakRule("rest","可休息","actual",0,240,null,"optional",false))));assertThat(new AttendanceJudgement().findings(s,session(s,start.plusSeconds(1800),end),List.of(),end.plusSeconds(1))).singleElement().extracting(ApprovalDtos.Finding::seconds).isEqualTo(1500L);}
 @Test void missingCardIsNotAutomaticAbsenceAndUnfinishedCancelledOrFullLeaveAreNotMissing(){var s=schedule(rules("full",List.of()));assertThat(new AttendanceJudgement().findings(s,null,List.of(),end.plusSeconds(1))).singleElement().extracting(ApprovalDtos.Finding::code).isEqualTo("MISSING");assertThat(new AttendanceJudgement().findings(s,null,List.of(),start)).isEmpty();assertThat(new AttendanceJudgement().findings(s,null,List.of(new ApprovalCalculator.LeaveSlice(start,end,true)),end.plusSeconds(1))).extracting(ApprovalDtos.Finding::code).containsExactly("LEAVE");}
 @Test void legacySessionNullFieldsRemainInSnapshotButNewRuleIdIsOmitted(){var mapper=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules();var s=schedule(null);var node=mapper.valueToTree(session(s,start,end));assertThat(node.has("breakStartedAt")).isTrue();assertThat(node.get("breakStartedAt").isNull()).isTrue();assertThat(node.has("breakStartedRuleId")).isFalse();assertThat(node.size()).isEqualTo(10);}
}
